insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-shell-gcp', 'Guest shell runs on Google Cloud', 'done', 'Google Cloud', 'Throwaway terminal per visitor behind an allowlist proxy; tested end to end.', 0);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-hub', 'Hub MCP with guest and owner commands', 'done', 'Assistants', 'Read-only tools, safe command drafting, agents and languages listed honestly.', 1);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-agents-cli', 'claude, gemini and copilot verified in both shell images', 'done', 'Assistants', 'The build now fails if any of the three cannot run.', 2);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-standby', 'Standby website on Cloud Run', 'done', 'Google Cloud', 'Refreshed by re-running Setup-GcpStandby.ps1.', 3);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-obs', 'Logging, metrics, alerts, dashboard and BigQuery analytics', 'done', 'Google Cloud', 'Five alert policies; no visitor IP addresses are stored.', 4);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-proxy', 'Proxy VM on a least-privilege account', 'done', 'Google Cloud', 'It can only write logs and metrics.', 5);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-status', 'Live status feed and status page', 'done', 'Website', 'Updates every 5 minutes; goes stale visibly; alert if the recorder stops.', 6);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-audit', 'Weekly audit with score, fixes and maps', 'done', 'Google Cloud', 'Mondays 09:00 Los Angeles time; reports kept 180 days.', 7);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-miner', 'Rabbit web data miner on the Maxwell chain', 'done', 'Chain', 'Block 2 mined; the daily job runs it from the next 3:00 AM run.', 8);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('d-supabase-tree', 'Supabase tree, checked against the live database', 'done', 'Supabase', '29 tables; the 8 closed ones refuse an anonymous reader.', 9);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-browser-test', 'Try the guest shell in a browser', 'waiting', 'You', 'Needs the human check, which only a person can pass.', 10);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-sql', 'Apply the platform-graph SQL in the Supabase SQL editor', 'waiting', 'You', 'Two files: the tables, then the data. Nothing is written until you run them.', 11);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-push', 'Push the local commits to GitHub', 'waiting', 'You', 'All three repositories have commits that exist only on this computer.', 12);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-app-deploy', 'Deploy the RabbitOS app', 'waiting', 'You', 'Adds the prompt box, key toggle and save/restore buttons to the guest shell page.', 13);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-owner-key', 'Create a hub key and test the owner role', 'waiting', 'You', 'Run New-HubKey.ps1; the key goes to the clipboard and is never printed.', 14);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-credits', 'Check the Google Cloud credit balance and its terms', 'waiting', 'You', 'It cannot be read from here.', 15);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-relink', 'Relink the local audit chain', 'waiting', 'You', 'From the 2026-10-09 notes: python .\relink_audit_once.py, then python .\rabbit_sync.py. May already be done.', 16);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-contact-key', 'Back up the contact-records private key offline, in two places', 'waiting', 'You', 'From the 2026-10-09 notes; before opening sign-ups.', 17);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('w-privacy', 'Update privacy.html', 'waiting', 'You', 'Draft in docs/privacy-page-change.md; has decisions only you can make.', 18);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-titles', 'Give every RabbitOS page its own title', 'next', 'Audit', '38 pages share a title; the app''s pages are all just ''RabbitOS''.', 19);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-descriptions', 'Add meta descriptions to 5 website pages', 'next', 'Audit', 'local, agent, license, recovery, dna-code.', 20);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-h1', 'Add a main heading to /downloads in the app', 'next', 'Audit', '', 21);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-csp', 'Enforce the app''s Content Security Policy', 'next', 'Audit', 'It is report-only today; the csp-enforce-public branch exists.', 22);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-sitemap', 'Publish a sitemap for the app', 'next', 'Audit', '', 23);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-previews', 'Add canonical addresses and link previews', 'next', 'Audit', 'Low priority; every page lacks them.', 24);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('n-egress', 'Review refused egress requests each month', 'next', 'Google Cloud', 'A BigQuery query in docs/gcp-observability.md shows which hosts visitors ask for.', 25);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('l-failover', 'Put the failover Worker on the live route', 'later', 'Website', 'Written and tested. Use fail-open routing; test on a separate address first.', 26);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('l-xrpl', 'Anchor Merkle roots on the XRPL', 'later', 'Chain', 'Needs a wallet secret stored as a Cloudflare secret, never pasted in chat.', 27);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('l-vault', 'Personal-data vault with grants', 'later', 'Privacy', 'Not started. Personal data stays on the owner''s computer until then.', 28);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('p-signups', 'Open sign-ups', 'paused', 'RabbitOS', 'Stays off in Supabase until the live checks pass.', 29);
insert into public.platform_roadmap (id, title, status, area, note, sort_order) values ('p-k8s', 'Kubernetes cluster', 'paused', 'Google Cloud', 'Optional. Cloud Run covers the needs today; Setup-GcpGke.ps1 is ready.', 30);
